function OverseaChatMessageCell:__init()
    self.data = nil
    ---@type CommonPlayerHeadNode
    self.playerHeadEnv = nil
    ---@type UnityEngine.RectTransform
    self.btnTranslateTrans = nil
    ---@type UnityEngine.RectTransform
    self.translateTextTrans = nil
end

function OverseaChatMessageCell:__delete()
    self.data = nil
    self.playerHeadEnv = nil
end

function OverseaChatMessageCell:Awake()
    self.playerHeadEnv = CfUtils.GetLuaScr(self.CommonPlayerHeadNode, CommonPlayerHeadNode)
    self.btnTranslateTrans = self.Dialogue.transform:Find("BtnTranslate")
    --转换后的文本内容
    self.translateTextTrans = self.Dialogue.transform:Find("TextTranslate")
    if self.btnTranslateTrans then
        KTool.SetActive(self.btnTranslateTrans.gameObject, false)
    end
end

---FreshUI
---@param data table
---@param myPlayerId number 当前角色id
---@param otherPlayerName string 聊天的玩家名
---@param friendData table 聊天的玩家数据
function OverseaChatMessageCell:FreshUI(data, myPlayerId, otherPlayerName, friendData)
    self.data = data
    local msgType = checkInt(data.msgType)

    KTool.SetActive(self.Emoji.gameObject, msgType == ChatConstants.ChatMsgType.EMOJI)
    KTool.SetActive(self.Dialogue.gameObject, msgType ~= ChatConstants.ChatMsgType.EMOJI)

    if data.chatChannel == ChatConstants.ChatServerChannel.CrossWorld then
        CfUtils.SetActive(self.TextArea, true)
        ---@type UserComponent
        local userComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent)
        local serverDojo = userComponent:GetServerListById(data.serverId)
        CfUtils.FillText(self.TextArea, string.format('[%s]', serverDojo.serverName))
    else
        CfUtils.SetActive(self.TextArea, false)
    end
    
    ---@type PlayerComponent
    local playerComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    if checkInt(data.sendPlayerId) == checkInt(myPlayerId) then
        ---我发送的
        CfUtils.FillText(self.TextName, playerComp.playerDojo.playerName)
        if self.playerHeadEnv then
            self.playerHeadEnv:FreshAvatarFrame(playerComp.playerDojo.playerAvatar, playerComp.playerDojo.playerAvatarFrame)
            self.playerHeadEnv:SetCallBack(function()  end)
        end
    else
        if self.playerHeadEnv then
            self.playerHeadEnv:FreshAvatarFrame(friendData.avatar, friendData.avatarFrame)
            self.playerHeadEnv:SetCallBack(function ()
                local serverId = SDKService:GetServerIdAndServerName()
                local hideFriendBtn = data.serverId and checkInt(data.serverId) ~= checkInt(serverId)
                -- 直接进入 他人的 个人信息界面2D版 
                GameUtils.ShowPlayerInfo(
                    friendData.playerId or friendData.friendId, 
                    nil,
                    nil,
                     {panelMode = true, chatEnter = true, message = data.message or data.content, hideFriendBtn = hideFriendBtn}    
                )
                -- 下方为旧方案, 暂被替代:
                -- GameUtils.ShowCommonPlayerHeadOption(self.CommonPlayerHeadNode.gameObject, Constants.PlayerHeadOptionType.CHAT,{
                --     playerId    = friendData.playerId or friendData.friendId,
                --     name        = friendData.name,
                --     level       = friendData.level,
                --     avatar      = friendData.avatar,
                --     avatarFrame = friendData.avatarFrame,
                -- })
            end)
        end
        CfUtils.FillText(self.TextName, otherPlayerName)
    end
    ---头像处理
    if msgType == ChatConstants.ChatMsgType.EMOJI then
        local _, _, _, goodsId = string.find(data.content, "^#(%[)(%d+)(%])#$")
        if goodsId then
            ---@type GoodsEmojiVo
            local vo = CfUtils.GetCfVo(AutoIds.IdSetting2768, "GoodsEmojiVo", goodsId)
            if vo then
                CfUtils.FillImage(self.ImgIcon, vo.photoPath)
            end
        end
    else
        CfUtils.FillText(self.TextDesc, tostring(data.content))
        -----@type UnityEngine.RectTransform
        --local bgRectTrans = KTool.GetComponent(self.controller.gameObject, typeof(RectTransform))
        --local size = bgRectTrans.sizeDelta
        -----@type UnityEngine.RectTransform
        --local contentRect = KTool.GetComponent(self.Dialogue.gameObject, typeof(RectTransform))
        --print('--->>>', size, contentRect.sizeDelta)
        --size.x = 786 + 20
        --size.y = contentRect.sizeDelta.y + 20
        --print('--->>', size, contentRect.sizeDelta)
        --bgRectTrans.sizeDelta = size

        --local y = sizeDelta.y + 20
        --if y < 76 then
        --    y = 76
        --end
        --rectTrans:SetSizeWithCurrentAnchors(CS.UnityEngine.RectTransform.Axis.Vertical, y)
        -----@type UnityEngine.UI.VerticalLayoutGroup
        --local verticalLayoutGroup = KTool.GetComponent(self.controller.gameObject, typeof(CS.UnityEngine.UI.VerticalLayoutGroup))
        --verticalLayoutGroup:CalculateLayoutInputVertical()
    end
    local rectTrans = KTool.GetComponent(self.controller.gameObject, typeof(RectTransform))
    CS.UnityEngine.UI.LayoutRebuilder.ForceRebuildLayoutImmediate(rectTrans)
end

